const pruneComposerVersions = `-- name: PruneComposerVersions :execrows
DELETE FROM campaign_versions v
WHERE v.campaign_id = $1 AND v.source = 'autosave' AND v.version <> 1 AND v.name = ''
  AND v.version <= (SELECT max(x.version) FROM campaign_versions x WHERE x.campaign_id = $1) - $2::int
`

type PruneComposerVersionsParams struct {
	CampaignID uuid.UUID `json:"campaignId"`
	Keep       int32     `json:"keep"`
}

// Keeps the newest @keep versions; the first version, named versions and
// anything that is not an autosave (restores, imports, ⌘S) are always kept.
func (q *Queries) PruneComposerVersions(ctx context.Context, arg PruneComposerVersionsParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneComposerVersions, arg.CampaignID, arg.Keep)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const purgeDeletedCampaigns = `-- name: PurgeDeletedCampaigns :execrows
DELETE FROM campaigns c
WHERE c.id IN (SELECT x.id FROM campaigns x WHERE x.deleted_at IS NOT NULL AND x.deleted_at < $1 LIMIT 500)
  AND NOT EXISTS (SELECT 1 FROM messages m WHERE m.campaign_id = c.id AND m.status NOT IN ('queued', 'held', 'cancelled', 'failed', 'rejected'))
`

// Deleted campaigns go for good 30 days on (CA-1); one that sent anything
// never was deletable, but the check stays.
func (q *Queries) PurgeDeletedCampaigns(ctx context.Context, before *time.Time) (int64, error) {
	result, err := q.db.Exec(ctx, purgeDeletedCampaigns, before)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

